using System;
using System.IO;
using System.Security.Cryptography;
using Aspose.Cells;

// The program creates an Aspose.Cells workbook, saves it as a TIFF image, computes the SHA256 checksum of the resulting file using .NET's SHA256 class, and prints the hash for integrity verification.
class Program
{
    static void Main()
    {
        // Create a new workbook (using the provided creation rule)
        Workbook workbook = new Workbook();

        // Add some sample data to the first worksheet
        Worksheet sheet = workbook.Worksheets[0];
        sheet.Cells["A1"].PutValue("Product");
        sheet.Cells["B1"].PutValue("Quantity");
        sheet.Cells["A2"].PutValue("Apples");
        sheet.Cells["B2"].PutValue(150);
        sheet.Cells["A3"].PutValue("Oranges");
        sheet.Cells["B3"].PutValue(200);

        // Define the output TIFF file path
        string tiffPath = "output.tiff";

        // Save the workbook as a TIFF image (using the provided save rule)
        workbook.Save(tiffPath, SaveFormat.Tiff);

        // Generate a SHA256 checksum for the saved TIFF file
        string checksum = ComputeSha256Checksum(tiffPath);

        // Output the checksum for verification
        Console.WriteLine($"SHA256 checksum of '{tiffPath}': {checksum}");
    }

    // Helper method to compute SHA256 checksum of a file
    private static string ComputeSha256Checksum(string filePath)
    {
        using (FileStream stream = File.OpenRead(filePath))
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] hashBytes = sha256.ComputeHash(stream);
            // Convert hash bytes to a hexadecimal string
            return BitConverter.ToString(hashBytes).Replace("-", string.Empty).ToLowerInvariant();
        }
    }
}
